import React, { useRef } from 'react';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import { Download } from 'lucide-react';

const IDCard = ({ student }) => {
  const cardRef = useRef(null);

  const issueYear = new Date().getFullYear();
  const expiryYear = issueYear + (student.programme && student.programme.includes('DIPLOMA') ? 2 : 4);

  const downloadPDF = async () => {
    if (!cardRef.current) return;
    const canvas = await html2canvas(cardRef.current, { scale: 4, useCORS: true });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('landscape', 'mm', [85.6, 54]);
    pdf.addImage(imgData, 'PNG', 0, 0, 85.6, 54);
    pdf.save(`${student.reg_no.replace(/\//g, '-')}_ID_Card.pdf`);
  };

  const sigBase64 = "data:image/png;base64,";
  const kemuLogo = "data:image/svg+xml;base64,";

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>

      <div
        ref={cardRef}
        style={{
          width: '856px',
          height: '540px',
          backgroundColor: '#fdfdfd',
          borderRadius: '16px',
          overflow: 'hidden',
          boxShadow: '0 10px 30px rgba(0,0,0,0.2)',
          position: 'relative',
          fontFamily: "Arial, Helvetica, sans-serif",
          color: '#1A2D5C',
          display: 'flex',
          flexDirection: 'column'
        }}
      >
        {/* Logo Watermark */}
        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, zIndex: 1, opacity: 0.10, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <img src={kemuLogo} alt="KeMU Watermark" style={{ width: '680px', height: '680px', objectFit: 'contain', marginTop: '120px' }} />
        </div>

        {/* TOP HEADER AREA */}
        <div style={{
          position: 'absolute',
          top: 0, left: 0, right: 0, height: '160px',
          background: '#6B235E', // Solid purple base
          zIndex: 2,
          borderBottom: '6px solid #D4AF37' // Gold line
        }}>

          {/* Diagonal Blue shape on the top left */}
          <div style={{
            position: 'absolute',
            top: 0, left: 0,
            width: '60%',
            height: '100%',
            background: '#142750', // A slightly darker blue as seen in the image
            clipPath: 'polygon(0 0, 95% 0, 0 95%)', // Creates the diagonal cut
            zIndex: 1 // sits behind the text
          }}></div>

          {/* Header Text Content */}
          <div style={{ padding: '30px 40px 15px 40px', textAlign: 'center', position: 'relative', zIndex: 3 }}>
            <h1 style={{
              margin: '0',
              color: '#D4AF37',
              fontFamily: "'Times New Roman', Times, serif",
              fontSize: '44px',
              fontWeight: 'bold',
              letterSpacing: '1px',
              textShadow: '2px 2px 4px rgba(0,0,0,0.5), -1px -1px 0 rgba(255,255,255,0.2)'
            }}>
              KENYA METHODIST UNIVERSITY
            </h1>
            <p style={{
              margin: '6px 0 0 0',
              color: '#ffffff',
              fontSize: '17px',
              lineHeight: '1.4',
              fontFamily: "Arial, sans-serif",
              fontWeight: '500'
            }}>
              P.O. BOX 267-60200 Meru<br />
              Tel: (+254-020) 2118423-7, 064-30301/31229 Fax: (+254-0647)<br />
              Email: info@kemu.ac.ke website: www.kemu.ac.ke
            </p>
          </div>
        </div>

        {/* Right side diagonal polygons */}
        {/* Large blue shape */}
        <div style={{
          position: 'absolute',
          right: 0,
          top: '166px', // Starts just below the gold line
          width: '280px',
          height: '400px',
          background: '#1A2D5C',
          clipPath: 'polygon(100% 0, 100% 100%, 0 100%, 35% 0)', // Slanted left edge
          zIndex: 1
        }}></div>

        {/* Small purple shape at bottom right */}
        <div style={{
          position: 'absolute',
          right: 0,
          bottom: 0,
          width: '180px',
          height: '180px',
          background: '#6B235E',
          clipPath: 'polygon(100% 100%, 0 100%, 100% 0)',
          zIndex: 1
        }}></div>

        {/* 4 Gold horizontal stripes on the left */}
        <div style={{ position: 'absolute', left: 0, top: '280px', display: 'flex', flexDirection: 'column', gap: '14px', zIndex: 2 }}>
          <div style={{ width: '40px', height: '5px', backgroundColor: '#D4AF37' }}></div>
          <div style={{ width: '30px', height: '5px', backgroundColor: '#D4AF37' }}></div>
          <div style={{ width: '45px', height: '5px', backgroundColor: '#D4AF37' }}></div>
          <div style={{ width: '35px', height: '5px', backgroundColor: '#D4AF37' }}></div>
        </div>

        {/* Main Content Body */}
        <div style={{ position: 'absolute', top: '166px', left: 0, right: 0, bottom: 0, padding: '25px 40px', display: 'flex', zIndex: 3 }}>

          {/* Left Details */}
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
            <h2 style={{
              margin: '10px 0 8px 0',
              color: '#1A2D5C',
              fontSize: '36px',
              fontWeight: '900',
              fontFamily: 'Georgia, "Times New Roman", serif',
              textTransform: 'uppercase',
              letterSpacing: '0.5px'
            }}>
              {student.name}
            </h2>
            <h3 style={{
              margin: '0 0 35px 0',
              color: '#6B235E',
              fontSize: '19px',
              fontWeight: '700',
              textTransform: 'uppercase',
              fontFamily: "Arial, sans-serif",
              maxWidth: '85%'
            }}>
              {student.programme || 'Student Programme'}
            </h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '14px', fontSize: '20px', fontWeight: '700', color: '#1A2D5C', fontFamily: "Arial, sans-serif" }}>
              <div style={{ display: 'flex' }}>
                <span style={{ width: '220px' }}>ADMISSION NO.</span>
                <span style={{ color: '#000', fontWeight: '600' }}>{student.reg_no}</span>
              </div>
              <div style={{ display: 'flex' }}>
                <span style={{ width: '220px' }}>DATE OF ISSUE:</span>
                <span style={{ color: '#000', fontWeight: '600' }}>{issueYear}</span>
              </div>
              <div style={{ display: 'flex' }}>
                <span style={{ width: '220px' }}>EXPIRY DATE:</span>
                <span style={{ color: '#000', fontWeight: '600' }}>{expiryYear}</span>
              </div>
            </div>
          </div>

          {/* Right Photo */}
          <div style={{
            width: '210px',
            height: '210px',
            borderRadius: '50%',
            border: '6px solid #D4AF37',
            outline: '2px solid #ffffff',
            outlineOffset: '-8px',
            overflow: 'hidden',
            backgroundColor: '#f0f0f0',
            position: 'absolute',
            right: '50px',
            top: '30px',
            boxShadow: '0 10px 20px rgba(0,0,0,0.3)'
          }}>
            <img
              src={student.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(student.name)}&background=1A2D5C&color=fff&size=400`}
              alt={student.name}
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              crossOrigin="anonymous"
            />
          </div>

          {/* NFC Icon */}
          <div style={{
            position: 'absolute',
            right: '115px',
            top: '260px',
            color: '#D4AF37',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center'
          }}>
            <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M4 8.242C2.121 9.94 1 12.336 1 15v3.5a1.5 1.5 0 0 0 1.5 1.5h19a1.5 1.5 0 0 0 1.5-1.5V15c0-2.664-1.121-5.06-2.999-6.758" />
              <path d="M7 11.242C5.642 12.43 4.8 14.113 4.8 16v3" />
              <path d="M10 14.242A5.19 5.19 0 0 0 8.6 17v2" />
              <path d="M13.6 17v2" />
              <path d="M17 11.242C18.358 12.43 19.2 14.113 19.2 16v3" />
            </svg>
            <span style={{ fontSize: '12px', fontWeight: '900', color: '#1A2D5C', marginTop: '5px' }}>NFC ENABLED</span>
          </div>
        </div>

        {/* Footer Bottom Elements */}
        <div style={{
          position: 'absolute',
          bottom: 0, left: 0, right: 0,
          height: '110px',
          zIndex: 4,
          padding: '0 40px',
          display: 'flex',
          alignItems: 'flex-end'
        }}>

          {/* Logo Extracted from Image */}
          <div style={{
            width: '110px',
            height: '110px',
            marginBottom: '15px',
            marginLeft: '-15px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            <img src={kemuLogo} alt="KeMU Logo" style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
          </div>

          {/* Custom SVG Signature */}
          <div style={{ marginLeft: '5px', paddingBottom: '40px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ width: '120px', height: '35px', marginLeft: '10px' }}>
              <img src={sigBase64} alt="Registrar Signature" style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
            </div>
            <div style={{ borderTop: '2px solid #1A2D5C', width: '180px', paddingTop: '4px' }}>
              <span style={{ fontSize: '12px', fontWeight: '700', color: '#000', fontFamily: "Arial, sans-serif" }}>Authorizing Signature</span>
            </div>
          </div>

          {/* Student ID Banner Container */}
          <div style={{
            position: 'absolute',
            bottom: '35px',
            right: '40px',
            width: '460px',
            height: '42px',
            background: 'linear-gradient(90deg, #ffffff 0%, #f0f0f0 100%)',
            borderTop: '3px solid #1A2D5C',
            borderBottom: '3px solid #1A2D5C',
            transform: 'skewX(-20deg)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: '-4px 4px 8px rgba(0,0,0,0.15)'
          }}>
            <div style={{ transform: 'skewX(20deg)', display: 'flex', gap: '10px', alignItems: 'center' }}>
              <span style={{ color: '#1A2D5C', fontWeight: '900', fontSize: '24px', letterSpacing: '1px', fontFamily: "Arial, sans-serif" }}>STUDENT</span>
              <span style={{ color: '#D4AF37', fontWeight: '900', fontSize: '24px', letterSpacing: '1px', textShadow: '0 1px 2px rgba(0,0,0,0.2)', fontFamily: "Arial, sans-serif" }}>IDENTIFICATION</span>
              <span style={{ color: '#1A2D5C', fontWeight: '900', fontSize: '24px', letterSpacing: '1px', fontFamily: "Arial, sans-serif" }}>CARD</span>
            </div>
          </div>

          {/* Fine Print */}
          <div style={{
            position: 'absolute',
            bottom: '8px',
            left: '40px',
            right: '40px',
            fontSize: '11px',
            fontWeight: '600',
            lineHeight: '1.2',
            color: '#333',
            fontFamily: "Arial, sans-serif",
            paddingRight: '150px'
          }}>
            This card is a property of Kenya Methodist University and must be returned on demand or upon expiry.<br />
            It incorporates advanced micro-textured elements for authentication.
          </div>
        </div>
      </div>

      <button
        onClick={downloadPDF}
        className="btn btn-primary"
        style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '1rem', padding: '0.75rem 1.5rem', fontSize: '1.1rem' }}
      >
        <Download size={20} />
        Download High-Res ID Card
      </button>
    </div>
  );
};

export default IDCard;

